package org.securemail.client.ecosystem;

import java.io.*;
import java.security.MessageDigest;
import java.util.*;
import org.securemail.ecosystem.protocol.IdentityProtocol;

/** Purpose-specific Mail consent protocol. There is deliberately no arbitrary payload-to-sign operation. */
public final class MailPairing600 {
  public static final String PURPOSE_REGISTER="AEGIS6-PAIRING-REGISTER",PURPOSE_STEP_UP="AEGIS6-PAIRING-STEPUP",PURPOSE_VOICE="AEGIS6-PAIRING-VOICE",PURPOSE_OWNER_TRANSFER="AEGIS6-PAIRING-OWNER-TRANSFER",PURPOSE_FIRST_DELEGATE="AEGIS6-PAIRING-FIRST-DELEGATE",PURPOSE_OWNER_BOOTSTRAP="AEGIS6-PAIRING-OWNER-BOOTSTRAP",PURPOSE_DEVICE_RECOVERY="AEGIS6-PAIRING-DEVICE-RECOVERY";
  private MailPairing600(){}
  public sealed interface Request permits RegistrationRequest,StepUpRequest,VoiceDelegationRequest,OwnerTransferRequest,FirstDelegateRequest,OwnerBootstrapRequest,DeviceRecoveryRequest {}
  public record RegistrationRequest(byte[] devicePublic) implements Request {
    public RegistrationRequest{IdentityProtocol.publicKey(devicePublic);devicePublic=devicePublic.clone();}
    @Override public byte[] devicePublic(){return devicePublic.clone();}
  }
  public record StepUpRequest(String aegisCapability,long requestTime,String requestNonce,byte[] appProof) implements Request {
    public StepUpRequest{IdentityProtocol.Capability cap=IdentityProtocol.decodeCapability(aegisCapability);if(cap.appId!=IdentityProtocol.App.AEGIS||requestTime<0||appProof.length!=64)throw new IllegalArgumentException("Некорректное подтверждение входа");IdentityProtocol.nonceValue(requestNonce);appProof=appProof.clone();}
    @Override public byte[] appProof(){return appProof.clone();}
    @Override public String toString(){return "StepUpRequest[redacted]";}
  }
  public record VoiceDelegationRequest(String glasCapability,long requestTime,String requestNonce,byte[] appProof) implements Request {
    public VoiceDelegationRequest{var cap=IdentityProtocol.decodeCapability(glasCapability);if(cap.appId!=IdentityProtocol.App.GLAS||!cap.capabilities.containsAll(Set.of(IdentityProtocol.Scope.VOICE_CALL,IdentityProtocol.Scope.CONTACTS_READ))||requestTime<0||appProof==null||appProof.length!=64)throw new IllegalArgumentException("Некорректное разрешение Гласа");IdentityProtocol.nonceValue(requestNonce);appProof=appProof.clone();}
    @Override public byte[] appProof(){return appProof.clone();}@Override public String toString(){return "VoiceDelegationRequest[redacted]";}
  }
  public record OwnerTransferRequest(String aegisCapability,IdentityProtocol.OwnerTransfer transfer,IdentityProtocol.OwnerTransferRole intent,long requestTime,String requestNonce,byte[] appProof) implements Request {
    public OwnerTransferRequest{var cap=IdentityProtocol.decodeCapability(aegisCapability);Objects.requireNonNull(transfer);Objects.requireNonNull(intent);boolean owner=intent==IdentityProtocol.OwnerTransferRole.OWNER_APPROVE;if(cap.appId!=IdentityProtocol.App.AEGIS||!cap.capabilities.contains(IdentityProtocol.Scope.ACCOUNT_READ)||!cap.audience.equals(transfer.audience)||!cap.accountId.equals(owner?transfer.ownerAccountId:transfer.targetAccountId)||!cap.deviceId.equals(owner?transfer.ownerDeviceId:transfer.targetDeviceId)||cap.generation!=(owner?transfer.ownerGeneration:transfer.targetGeneration)||requestTime<0||appProof==null||appProof.length!=64)throw new IllegalArgumentException("Некорректное подтверждение передачи владельца");IdentityProtocol.nonceValue(requestNonce);appProof=appProof.clone();}
    @Override public byte[] appProof(){return appProof.clone();}@Override public String toString(){return "OwnerTransferRequest[public typed consent]";}
  }
  public record OwnerTransferResult(byte[] accountPublic,IdentityProtocol.OwnerTransfer transfer,IdentityProtocol.OwnerTransferRole intent,byte[] accountProof) {
    public OwnerTransferResult{IdentityProtocol.publicKey(accountPublic);Objects.requireNonNull(transfer);Objects.requireNonNull(intent);String expected=intent==IdentityProtocol.OwnerTransferRole.OWNER_APPROVE?transfer.ownerAccountId:transfer.targetAccountId;if(!IdentityProtocol.id(accountPublic).equals(expected)||accountProof==null||accountProof.length!=64)throw new IllegalArgumentException("Некорректное подтверждение передачи владельца");accountPublic=accountPublic.clone();accountProof=accountProof.clone();}
    @Override public byte[] accountPublic(){return accountPublic.clone();}@Override public byte[] accountProof(){return accountProof.clone();}
  }
  public record FirstDelegateRequest(String aegisCapability,IdentityProtocol.FirstDelegation delegation,IdentityProtocol.FirstDelegateRole intent,long requestTime,String requestNonce,byte[] appProof) implements Request {
    public FirstDelegateRequest{var cap=IdentityProtocol.decodeCapability(aegisCapability);Objects.requireNonNull(delegation);Objects.requireNonNull(intent);boolean owner=intent==IdentityProtocol.FirstDelegateRole.OWNER_APPROVE;if(cap.appId!=IdentityProtocol.App.AEGIS||!cap.capabilities.contains(IdentityProtocol.Scope.ACCOUNT_READ)||!cap.audience.equals(delegation.audience)||!cap.accountId.equals(owner?delegation.ownerAccountId:delegation.targetAccountId)||!cap.deviceId.equals(owner?delegation.ownerDeviceId:delegation.targetDeviceId)||cap.generation!=(owner?delegation.ownerGeneration:delegation.targetGeneration)||requestTime<0||appProof==null||appProof.length!=64)throw new IllegalArgumentException("Некорректное первое делегирование");IdentityProtocol.nonceValue(requestNonce);appProof=appProof.clone();}
    @Override public byte[] appProof(){return appProof.clone();}@Override public String toString(){return "FirstDelegateRequest[public typed consent]";}
  }
  public record FirstDelegateResult(byte[] accountPublic,IdentityProtocol.FirstDelegation delegation,IdentityProtocol.FirstDelegateRole intent,byte[] accountProof) {
    public FirstDelegateResult{IdentityProtocol.publicKey(accountPublic);Objects.requireNonNull(delegation);Objects.requireNonNull(intent);String expected=intent==IdentityProtocol.FirstDelegateRole.OWNER_APPROVE?delegation.ownerAccountId:delegation.targetAccountId;if(!IdentityProtocol.id(accountPublic).equals(expected)||accountProof==null||accountProof.length!=64)throw new IllegalArgumentException("Некорректное первое делегирование");accountPublic=accountPublic.clone();accountProof=accountProof.clone();}
    @Override public byte[] accountPublic(){return accountPublic.clone();}@Override public byte[] accountProof(){return accountProof.clone();}
  }
  public record OwnerBootstrapRequest(String aegisCapability,IdentityProtocol.OwnerBootstrap bootstrap,long requestTime,String requestNonce,byte[] appProof) implements Request {
    public OwnerBootstrapRequest{var cap=IdentityProtocol.decodeCapability(aegisCapability);Objects.requireNonNull(bootstrap);if(cap.appId!=IdentityProtocol.App.AEGIS||!cap.capabilities.contains(IdentityProtocol.Scope.ACCOUNT_READ)||!cap.audience.equals(bootstrap.audience)||!cap.accountId.equals(bootstrap.accountId)||requestTime<0||appProof==null||appProof.length!=64)throw new IllegalArgumentException("Некорректное первоначальное назначение владельца");IdentityProtocol.nonceValue(requestNonce);appProof=appProof.clone();}
    @Override public byte[] appProof(){return appProof.clone();}@Override public String toString(){return "OwnerBootstrapRequest[public typed consent]";}
  }
  public record OwnerBootstrapResult(byte[] accountPublic,IdentityProtocol.OwnerBootstrap bootstrap,byte[] accountProof) {
    public OwnerBootstrapResult{IdentityProtocol.publicKey(accountPublic);Objects.requireNonNull(bootstrap);if(!IdentityProtocol.id(accountPublic).equals(bootstrap.accountId)||accountProof==null||accountProof.length!=64)throw new IllegalArgumentException("Некорректное первоначальное назначение владельца");accountPublic=accountPublic.clone();accountProof=accountProof.clone();}
    @Override public byte[] accountPublic(){return accountPublic.clone();}@Override public byte[] accountProof(){return accountProof.clone();}
  }
  public record DeviceRecoveryRequest(IdentityProtocol.DeviceRecovery recovery,long requestTime,String requestNonce,byte[] deviceProof) implements Request {
    public DeviceRecoveryRequest{Objects.requireNonNull(recovery);IdentityProtocol.nonceValue(requestNonce);if(requestTime<0||deviceProof==null||deviceProof.length!=64||!IdentityProtocol.verify(recovery.newDevicePublic(),IdentityProtocol.deviceRecoveryInspection(recovery,requestTime,requestNonce),deviceProof))throw new IllegalArgumentException("Некорректный запрос восстановления устройства");deviceProof=deviceProof.clone();}
    @Override public byte[] deviceProof(){return deviceProof.clone();}@Override public String toString(){return "DeviceRecoveryRequest[public typed consent]";}
  }
  public record DeviceRecoveryResult(byte[] accountPublic,byte[] recoveryPublic,IdentityProtocol.DeviceRecovery recovery,byte[] accountProof,byte[] recoveryProof) {
    public DeviceRecoveryResult{IdentityProtocol.publicKey(accountPublic);IdentityProtocol.publicKey(recoveryPublic);Objects.requireNonNull(recovery);if(!IdentityProtocol.id(accountPublic).equals(recovery.accountId)||MessageDigest.isEqual(accountPublic,recoveryPublic)||accountProof==null||recoveryProof==null||accountProof.length!=64||recoveryProof.length!=64)throw new IllegalArgumentException("Некорректное подтверждение восстановления устройства");accountPublic=accountPublic.clone();recoveryPublic=recoveryPublic.clone();accountProof=accountProof.clone();recoveryProof=recoveryProof.clone();}
    @Override public byte[] accountPublic(){return accountPublic.clone();}@Override public byte[] recoveryPublic(){return recoveryPublic.clone();}@Override public byte[] accountProof(){return accountProof.clone();}@Override public byte[] recoveryProof(){return recoveryProof.clone();}
  }
  public record RegistrationResult(byte[] accountPublic,byte[] recoveryPublic,String nickname,long time,String nonce,byte[] accountProof) {
    public RegistrationResult{IdentityProtocol.publicKey(accountPublic);IdentityProtocol.publicKey(recoveryPublic);if(MessageDigest.isEqual(accountPublic,recoveryPublic)||nickname==null||nickname.isBlank()||nickname.length()>80||nickname.codePoints().anyMatch(Character::isISOControl)||time<0||accountProof.length!=64)throw new IllegalArgumentException("Некорректное подтверждение регистрации");IdentityProtocol.nonceValue(nonce);accountPublic=accountPublic.clone();recoveryPublic=recoveryPublic.clone();accountProof=accountProof.clone();}
    @Override public byte[] accountPublic(){return accountPublic.clone();}@Override public byte[] recoveryPublic(){return recoveryPublic.clone();}@Override public byte[] accountProof(){return accountProof.clone();}
    @Override public String toString(){return "PairingResult[public keys and typed proof]";}
  }
  public record StepUpResult(byte[] accountPublic,String accountId,String deviceId,long generation,String challenge,long expiresAt,byte[] accountProof) {
    public StepUpResult{IdentityProtocol.publicKey(accountPublic);IdentityProtocol.idValue(accountId);IdentityProtocol.idValue(deviceId);IdentityProtocol.nonceValue(challenge);if(!IdentityProtocol.id(accountPublic).equals(accountId)||generation<1||expiresAt<1||accountProof.length!=64)throw new IllegalArgumentException("Некорректное подтверждение личности");accountPublic=accountPublic.clone();accountProof=accountProof.clone();}
    @Override public byte[] accountPublic(){return accountPublic.clone();}@Override public byte[] accountProof(){return accountProof.clone();}
    @Override public String toString(){return "PairingResult[public keys and typed proof]";}
  }
  static byte[] requestBytes(Request request)throws IOException {
    var bytes=new ByteArrayOutputStream();var out=new DataOutputStream(bytes);out.writeUTF("AEGIS-MAIL-PAIRING-6/v1");
    if(request instanceof RegistrationRequest registration){out.writeByte(0);out.write(registration.devicePublic());}
    else if(request instanceof StepUpRequest step){out.writeByte(1);out.writeUTF(step.aegisCapability());out.writeLong(step.requestTime());out.writeUTF(step.requestNonce());out.write(step.appProof());}
    else if(request instanceof VoiceDelegationRequest voice){out.writeByte(2);out.writeUTF(voice.glasCapability());out.writeLong(voice.requestTime());out.writeUTF(voice.requestNonce());out.write(voice.appProof());}
    else if(request instanceof OwnerTransferRequest transfer){out.writeByte(3);out.writeUTF(transfer.aegisCapability());byte[] encoded=IdentityProtocol.ownerTransferBytes(transfer.transfer());out.writeInt(encoded.length);out.write(encoded);out.writeUTF(transfer.intent().name());out.writeLong(transfer.requestTime());out.writeUTF(transfer.requestNonce());out.write(transfer.appProof());}
    else if(request instanceof FirstDelegateRequest delegate){out.writeByte(4);out.writeUTF(delegate.aegisCapability());byte[] encoded=IdentityProtocol.firstDelegationBytes(delegate.delegation());out.writeInt(encoded.length);out.write(encoded);out.writeUTF(delegate.intent().name());out.writeLong(delegate.requestTime());out.writeUTF(delegate.requestNonce());out.write(delegate.appProof());}
    else if(request instanceof OwnerBootstrapRequest bootstrap){out.writeByte(5);out.writeUTF(bootstrap.aegisCapability());byte[] encoded=IdentityProtocol.ownerBootstrapBytes(bootstrap.bootstrap());out.writeInt(encoded.length);out.write(encoded);out.writeLong(bootstrap.requestTime());out.writeUTF(bootstrap.requestNonce());out.write(bootstrap.appProof());}
    else if(request instanceof DeviceRecoveryRequest recovery){out.writeByte(6);byte[] encoded=IdentityProtocol.deviceRecoveryBytes(recovery.recovery());out.writeInt(encoded.length);out.write(encoded);out.writeLong(recovery.requestTime());out.writeUTF(recovery.requestNonce());out.write(recovery.deviceProof());}
    else throw new IOException("Недопустимый запрос согласования");return bytes.toByteArray();
  }
  public static Request decodeRequest(byte[] bytes)throws IOException {
    if(bytes.length>8192)throw new IOException("Слишком большой запрос согласования");try(var in=new DataInputStream(new ByteArrayInputStream(bytes))){if(!in.readUTF().equals("AEGIS-MAIL-PAIRING-6/v1"))throw new IOException("Неверная цель согласования");int mode=in.readUnsignedByte();Request result=switch(mode){case 0->new RegistrationRequest(exact(in,44));case 1->new StepUpRequest(in.readUTF(),in.readLong(),in.readUTF(),exact(in,64));case 2->new VoiceDelegationRequest(in.readUTF(),in.readLong(),in.readUTF(),exact(in,64));case 3->new OwnerTransferRequest(in.readUTF(),IdentityProtocol.decodeOwnerTransfer(bounded(in,2048)),IdentityProtocol.OwnerTransferRole.valueOf(in.readUTF()),in.readLong(),in.readUTF(),exact(in,64));case 4->new FirstDelegateRequest(in.readUTF(),IdentityProtocol.decodeFirstDelegation(bounded(in,2048)),IdentityProtocol.FirstDelegateRole.valueOf(in.readUTF()),in.readLong(),in.readUTF(),exact(in,64));case 5->new OwnerBootstrapRequest(in.readUTF(),IdentityProtocol.decodeOwnerBootstrap(bounded(in,1024)),in.readLong(),in.readUTF(),exact(in,64));case 6->new DeviceRecoveryRequest(IdentityProtocol.decodeDeviceRecovery(bounded(in,1024)),in.readLong(),in.readUTF(),exact(in,64));default->throw new IOException("Неизвестная цель согласования");};if(in.read()!=-1)throw new IOException("Лишние данные согласования");return result;}catch(IllegalArgumentException e){throw new IOException("Некорректный запрос согласования",e);}
  }
  public static byte[] registrationResult(RegistrationResult result)throws IOException {var bytes=new ByteArrayOutputStream();var out=new DataOutputStream(bytes);out.writeUTF("AEGIS-MAIL-REGISTRATION-RESULT/v1");out.write(result.accountPublic());out.write(result.recoveryPublic());out.writeUTF(result.nickname());out.writeLong(result.time());out.writeUTF(result.nonce());out.write(result.accountProof());return bytes.toByteArray();}
  public static RegistrationResult decodeRegistrationResult(byte[] bytes)throws IOException {try(var in=input(bytes,"AEGIS-MAIL-REGISTRATION-RESULT/v1")){var result=new RegistrationResult(exact(in,44),exact(in,44),in.readUTF(),in.readLong(),in.readUTF(),exact(in,64));end(in);return result;}catch(IllegalArgumentException e){throw new IOException("Некорректное подтверждение регистрации",e);}}
  public static byte[] stepUpResult(StepUpResult result)throws IOException {var bytes=new ByteArrayOutputStream();var out=new DataOutputStream(bytes);out.writeUTF("AEGIS-MAIL-STEPUP-RESULT/v1");out.write(result.accountPublic());out.writeUTF(result.accountId());out.writeUTF(result.deviceId());out.writeLong(result.generation());out.writeUTF(result.challenge());out.writeLong(result.expiresAt());out.write(result.accountProof());return bytes.toByteArray();}
  public static StepUpResult decodeStepUpResult(byte[] bytes)throws IOException {try(var in=input(bytes,"AEGIS-MAIL-STEPUP-RESULT/v1")){var result=new StepUpResult(exact(in,44),in.readUTF(),in.readUTF(),in.readLong(),in.readUTF(),in.readLong(),exact(in,64));end(in);return result;}catch(IllegalArgumentException e){throw new IOException("Некорректное подтверждение входа",e);}}
  public static byte[] ownerTransferResult(OwnerTransferResult result)throws IOException {var bytes=new ByteArrayOutputStream();var out=new DataOutputStream(bytes);out.writeUTF("AEGIS-MAIL-OWNER-TRANSFER-RESULT/v1");out.write(result.accountPublic());byte[] transfer=IdentityProtocol.ownerTransferBytes(result.transfer());out.writeInt(transfer.length);out.write(transfer);out.writeUTF(result.intent().name());out.write(result.accountProof());return bytes.toByteArray();}
  public static OwnerTransferResult decodeOwnerTransferResult(byte[] bytes)throws IOException {try(var in=input(bytes,"AEGIS-MAIL-OWNER-TRANSFER-RESULT/v1")){var result=new OwnerTransferResult(exact(in,44),IdentityProtocol.decodeOwnerTransfer(bounded(in,2048)),IdentityProtocol.OwnerTransferRole.valueOf(in.readUTF()),exact(in,64));end(in);return result;}catch(IllegalArgumentException invalid){throw new IOException("Некорректное подтверждение передачи владельца",invalid);}}
  public static byte[] firstDelegateResult(FirstDelegateResult result)throws IOException {var bytes=new ByteArrayOutputStream();var out=new DataOutputStream(bytes);out.writeUTF("AEGIS-MAIL-FIRST-DELEGATE-RESULT/v1");out.write(result.accountPublic());byte[] delegation=IdentityProtocol.firstDelegationBytes(result.delegation());out.writeInt(delegation.length);out.write(delegation);out.writeUTF(result.intent().name());out.write(result.accountProof());return bytes.toByteArray();}
  public static FirstDelegateResult decodeFirstDelegateResult(byte[] bytes)throws IOException {try(var in=input(bytes,"AEGIS-MAIL-FIRST-DELEGATE-RESULT/v1")){var result=new FirstDelegateResult(exact(in,44),IdentityProtocol.decodeFirstDelegation(bounded(in,2048)),IdentityProtocol.FirstDelegateRole.valueOf(in.readUTF()),exact(in,64));end(in);return result;}catch(IllegalArgumentException invalid){throw new IOException("Некорректное первое делегирование",invalid);}}
  public static byte[] ownerBootstrapResult(OwnerBootstrapResult result)throws IOException {var bytes=new ByteArrayOutputStream();var out=new DataOutputStream(bytes);out.writeUTF("AEGIS-MAIL-OWNER-BOOTSTRAP-RESULT/v1");out.write(result.accountPublic());byte[] bootstrap=IdentityProtocol.ownerBootstrapBytes(result.bootstrap());out.writeInt(bootstrap.length);out.write(bootstrap);out.write(result.accountProof());return bytes.toByteArray();}
  public static OwnerBootstrapResult decodeOwnerBootstrapResult(byte[] bytes)throws IOException {try(var in=input(bytes,"AEGIS-MAIL-OWNER-BOOTSTRAP-RESULT/v1")){var result=new OwnerBootstrapResult(exact(in,44),IdentityProtocol.decodeOwnerBootstrap(bounded(in,1024)),exact(in,64));end(in);return result;}catch(IllegalArgumentException invalid){throw new IOException("Некорректное первоначальное назначение владельца",invalid);}}
  public static byte[] deviceRecoveryResult(DeviceRecoveryResult result)throws IOException {var bytes=new ByteArrayOutputStream();var out=new DataOutputStream(bytes);out.writeUTF("AEGIS-MAIL-DEVICE-RECOVERY-RESULT/v1");out.write(result.accountPublic());out.write(result.recoveryPublic());byte[] recovery=IdentityProtocol.deviceRecoveryBytes(result.recovery());out.writeInt(recovery.length);out.write(recovery);out.write(result.accountProof());out.write(result.recoveryProof());return bytes.toByteArray();}
  public static DeviceRecoveryResult decodeDeviceRecoveryResult(byte[] bytes)throws IOException {try(var in=input(bytes,"AEGIS-MAIL-DEVICE-RECOVERY-RESULT/v1")){var result=new DeviceRecoveryResult(exact(in,44),exact(in,44),IdentityProtocol.decodeDeviceRecovery(bounded(in,1024)),exact(in,64),exact(in,64));end(in);return result;}catch(IllegalArgumentException invalid){throw new IOException("Некорректное подтверждение восстановления устройства",invalid);}}
  private static byte[] bounded(DataInputStream in,int max)throws IOException{int length=in.readInt();if(length<1||length>max)throw new IOException("Размер передачи владельца");return exact(in,length);}
  private static DataInputStream input(byte[] bytes,String domain)throws IOException {if(bytes.length>8192)throw new IOException("Слишком большой ответ согласования");var in=new DataInputStream(new ByteArrayInputStream(bytes));if(!domain.equals(in.readUTF()))throw new IOException("Неверная цель ответа согласования");return in;}
  private static byte[] exact(DataInputStream in,int size)throws IOException{byte[] bytes=in.readNBytes(size);if(bytes.length!=size)throw new EOFException();return bytes;}
  private static void end(DataInputStream in)throws IOException{if(in.read()!=-1)throw new IOException("Лишние данные подтверждения");}
}
